import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Card, Flex, FlexProps, Typography } from 'antd';
import cn from 'classnames';

import ChartIcon from 'assets/images/icons/chart.svg?react';
import { ActionsChart, ReportSummaryItem, StatisticsRead } from 'entities/Report';

import styles from './ReportSummary.module.scss';

interface IReportSummaryProps extends FlexProps {
	stats?: StatisticsRead;
}

export const ReportSummary: FC<IReportSummaryProps> = ({ className, stats, ...props }) => {
	const { t } = useTranslation();

	if (!stats) return null;

	const getArrow = (current: number | string | null, prev: number | string | null) => {
		if (!current || !prev) return 'equal';
		if (Number(current) > Number(prev)) return 'up';
		if (Number(current) < Number(prev)) return 'down';
		return 'equal';
	};

	return (
		<Flex {...props} vertical gap={8} className={cn(className, styles.summary)}>
			<ReportSummaryItem
				icon="picture"
				arrow={getArrow(
					stats.metrics.current_period.avg_income_per_post,
					stats.metrics.prev_period.avg_income_per_post,
				)}
				summ={`${stats.metrics.current_period.avg_income_per_post} РУБ`}
				description={`${t('Средний доход с одного поста')}, РУБ`}
			/>
			<ReportSummaryItem
				icon="wallet"
				arrow={getArrow(
					stats.metrics.current_period.avg_income_per_action,
					stats.metrics.prev_period.avg_income_per_action,
				)}
				summ={`${stats.metrics.current_period.avg_income_per_action} РУБ`}
				description={t('Ср. заработок')}
			/>
			<ReportSummaryItem
				icon="magnet"
				arrow={getArrow(
					stats.metrics.current_period.approved_actions_count,
					stats.metrics.prev_period.approved_actions_count,
				)}
				summ={`${stats.metrics.current_period.approved_actions_count}`}
				description={t('Всего платных действий за период')}
			/>

			<Card variant="borderless">
				<Flex vertical gap={12}>
					<Typography.Text type="secondary">{t('Платные действия')}</Typography.Text>
					<ActionsChart stats={stats} />
				</Flex>
			</Card>

			<Button variant="outlined" color="primary" size="large" icon={<ChartIcon />} iconPosition="end">
				{t('Запросить полную статистику')}
			</Button>
		</Flex>
	);
};
