import { FC, HTMLAttributes } from 'react';

import { Pie } from '@ant-design/plots';

import { Badge, Flex, theme } from 'antd';

import { StatisticsRead } from 'entities/Report';

import styles from './ActionsChart.module.scss';

interface IActionsChartProps extends HTMLAttributes<HTMLDivElement> {
	stats?: StatisticsRead;
}

export const ActionsChart: FC<IActionsChartProps> = ({ stats, ...props }) => {
	const {
		token: { colorPrimary, blue6, cyan7, volcano7, purple7, magenta7, green7 },
	} = theme.useToken();

	if (!stats) return null;

	const colors = {
		'1': blue6,
		'2': cyan7,
		'3': volcano7,
		'4': purple7,
		'5': magenta7,
		'6': green7,
	};

	const data =
		stats.top_advcampaigns.map((advCampaign, i) => ({
			type: (i + 1).toString(),
			value: Number(advCampaign.approved_amount),
			label: advCampaign.advcampaign.name,
		})) || [];

	const config = {
		data,
		angleField: 'value',
		colorField: 'label',
		innerRadius: 0.6,
		label: false,
		legend: false,
		tooltip: false,
		style: {
			fill: ({ type }: { type: string }) => {
				return colors[type as keyof typeof colors] || colorPrimary;
			},
		},
	};

	return (
		<Flex {...props} gap={16}>
			<div className={styles.chart}>
				<Pie width={160} height={160} padding={0} margin={0} {...config} />
			</div>

			<Flex vertical gap={8} className={styles.legend}>
				{data.map((item) => (
					<Badge key={item.type} color={colors[item.type as keyof typeof colors]} text={item.label} />
				))}
			</Flex>
		</Flex>
	);
};
