import { FC, MouseEvent } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, Button, Drawer, DrawerProps, Flex, message } from 'antd';
import cn from 'classnames';

import DeleteIcon from 'assets/images/icons/delete.svg?react';
import { MOCK_IPost } from 'shared/consts/MOCK_FOR_CATALOG';

import styles from './DeletePostDrawer.module.scss';

interface IDeletePostDrawerProps extends DrawerProps {
	post: MOCK_IPost;
}

export const DeletePostDrawer: FC<IDeletePostDrawerProps> = ({ className, post, ...props }) => {
	const { t } = useTranslation();

	// TODO:
	const scheduledPosts = 4;
	const publishedPosts = 3;

	const deletePost = (e: MouseEvent) => {
		// TODO:
		props.onClose?.(e);
		console.log('remove post ', post.id);
		message.info({
			content: t('Пост удален'),
		});
	};

	return (
		<Drawer
			title={
				<Flex gap={8} align="center">
					<DeleteIcon className={styles.deletePostDrawer__icon} />
					{t('Удалить пост?')}
				</Flex>
			}
			placement="bottom"
			className={cn(className, styles.deletePostDrawer)}
			destroyOnHidden
			{...props}>
			{!!scheduledPosts && (
				<Badge
					status={'processing'}
					text={t('Запланированный пост останется в Планнере и будет опубликован вовремя')}
				/>
			)}

			{!!publishedPosts && (
				<Badge
					status={'success'}
					text={t('Опубликованные посты ({{items}}) будут доступны в Планнере, во вкладке «История постов»', {
						items: publishedPosts,
					})}
				/>
			)}

			<Flex gap={12} justify="space-between" className={styles.deletePostDrawer__actions}>
				<Button type={'primary'} onClick={props.onClose}>
					{t('Нет, оставить')}
				</Button>
				<Button variant={'solid'} color={'danger'} onClick={deletePost}>
					{t('Да, удалить')}
				</Button>
			</Flex>
		</Drawer>
	);
};
